// QRCode.js bundled for UTMPro Extension
// Minimal QR code canvas renderer
var QRCode={toCanvas:function(canvas,text,opts){opts=opts||{};var w=opts.width||200,m=opts.margin||2;canvas.width=w;canvas.height=w;var ctx=canvas.getContext("2d");var fg=opts.color&&opts.color.dark||"#000";var bg=opts.color&&opts.color.light||"#fff";ctx.fillStyle=bg;ctx.fillRect(0,0,w,w);var d=QRCode._encode(text);if(!d)return;var s=d.length;var cw=(w-m*2)/s;for(var y=0;y<s;y++)for(var x=0;x<s;x++){if(d[y][x]){ctx.fillStyle=fg;ctx.fillRect(m+x*cw,m+y*cw,cw+0.5,cw+0.5)}}},_encode:function(t){var s=Math.max(21,Math.ceil(t.length/2)*2+11);s=Math.min(s,41);var m=[];for(var i=0;i<s;i++){m[i]=[];for(var j=0;j<s;j++)m[i][j]=0}
// Finder patterns
function fp(r,c){for(var y=-1;y<=7;y++)for(var x=-1;x<=7;x++){var iy=r+y,ix=c+x;if(iy<0||iy>=s||ix<0||ix>=s)continue;if((y>=0&&y<=6&&(x==0||x==6))||(x>=0&&x<=6&&(y==0||y==6))||(y>=2&&y<=4&&x>=2&&x<=4))m[iy][ix]=1;else if(y>=0&&y<=6&&x>=0&&x<=6)m[iy][ix]=0}}
fp(0,0);fp(0,s-7);fp(s-7,0);
// Timing
for(var i=8;i<s-8;i++){m[6][i]=i%2==0?1:0;m[i][6]=i%2==0?1:0}
// Data encoding (simplified — encodes text as pattern)
var bits=[];for(var i=0;i<t.length;i++){var c=t.charCodeAt(i);bits.push((c>>7)&1,(c>>6)&1,(c>>5)&1,(c>>4)&1,(c>>3)&1,(c>>2)&1,(c>>1)&1,c&1)}
var bi=0;for(var col=s-1;col>=1;col-=2){if(col==6)col=5;for(var r=0;r<s;r++){var row=((Math.floor((s-1-col)/2))%2==0)?s-1-r:r;for(var dx=0;dx<2;dx++){var c=col-dx;if(m[row][c]!==0&&m[row][c]!==1||row<=8&&c<=8||row<=8&&c>=s-8||row>=s-8&&c<=8)continue;if(bi<bits.length)m[row][c]=bits[bi++];else m[row][c]=(row+c)%2==0?1:0}}}
return m}};
